import os
import sys
import json
import base64
import hmac
import hashlib
import datetime
import platform

# Vendor Master Secret Salt (used for HMAC signing)
# Keep this consistent so any key generated by generate_license.py will validate here.
MASTER_SALT = "PASSWISH-COMMERCIAL-LICENSE-SALT-v1-2026-SECURE"
LICENSE_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "license.dat")

def get_machine_id():
    """
    Extracts deterministic, unique hardware identifiers from the Windows host
    (Registry MachineGuid, Windows ProductId, C: Volume Serial, and System Architecture)
    without relying on deprecated tools like wmic.
    Gracefully falls back on Linux / Cloud environments.
    """
    raw_components = []

    # 1. Windows MachineGuid (unique per Windows installation)
    try:
        import winreg
        reg = winreg.ConnectRegistry(None, winreg.HKEY_LOCAL_MACHINE)
        key = winreg.OpenKey(reg, r"SOFTWARE\Microsoft\Cryptography")
        guid, _ = winreg.QueryValueEx(key, "MachineGuid")
        raw_components.append(str(guid).strip().lower())
    except Exception:
        raw_components.append("default-guid")

    # 2. Windows ProductId
    try:
        import winreg
        reg = winreg.ConnectRegistry(None, winreg.HKEY_LOCAL_MACHINE)
        key = winreg.OpenKey(reg, r"SOFTWARE\Microsoft\Windows NT\CurrentVersion")
        pid, _ = winreg.QueryValueEx(key, "ProductId")
        raw_components.append(str(pid).strip().lower())
    except Exception:
        pass

    # 3. System Volume C: Serial Number via Windows kernel32
    try:
        import ctypes
        serial = ctypes.c_ulong()
        ctypes.windll.kernel32.GetVolumeInformationW("C:\\", None, 0, ctypes.byref(serial), None, None, None, 0)
        raw_components.append(hex(serial.value))
    except Exception:
        pass

    # 4. Computer Name & Node
    raw_components.append(platform.node().lower())

    combined = ":".join(raw_components)
    digest = hashlib.sha256(combined.encode("utf-8")).hexdigest().upper()

    # Format cleanly as: PW-XXXX-XXXX-XXXX-XXXX
    return f"PW-{digest[0:4]}-{digest[4:8]}-{digest[8:12]}-{digest[12:16]}"

def create_license_signature(payload_bytes):
    """Generates HMAC-SHA256 signature for the given payload."""
    return hmac.new(MASTER_SALT.encode("utf-8"), payload_bytes, hashlib.sha256).hexdigest()

def verify_license_token(token_str):
    """
    Validates a license token string.
    Returns: (is_valid, message, info_dict)
    """
    if not token_str or not isinstance(token_str, str):
        return False, "License token is empty.", None

    token_str = token_str.strip()
    if token_str.startswith("LIC-"):
        token_str = token_str[4:]

    parts = token_str.split(".")
    if len(parts) != 2:
        return False, "Invalid license format. Expected Payload.Signature format.", None

    payload_b64, signature = parts[0], parts[1]

    # Verify HMAC signature first
    try:
        payload_bytes = base64.urlsafe_b64decode(payload_b64.encode("utf-8"))
        expected_sig = create_license_signature(payload_bytes)
        if not hmac.compare_digest(expected_sig, signature):
            return False, "Tampered or invalid license signature.", None

        info = json.loads(payload_bytes.decode("utf-8"))
    except Exception as e:
        return False, f"Corrupted license payload: {e}", None

    licensed_machine = info.get("machine_id", "").upper().strip()
    current_machine = get_machine_id().upper().strip()

    # Check Machine ID Binding (Skip if wildcard "ALL" or "WEB" or running in Web/Cloud mode)
    if licensed_machine not in ("ALL", "ANY", "WEB", "CLOUD") and licensed_machine != current_machine:
        # If in web or cloud environment, permit wildcard access
        if not (os.environ.get('WEB_MODE') or os.environ.get('RENDER')):
            return (
                False,
                f"License is locked to a different computer ({licensed_machine}). Current machine is {current_machine}.",
                info
            )

    # Check Expiration Date
    expiry_str = info.get("expiry", "").upper().strip()
    if expiry_str != "LIFETIME":
        try:
            exp_date = datetime.datetime.strptime(expiry_str, "%Y-%m-%d").date()
            today = datetime.date.today()
            if today > exp_date:
                return False, f"License expired on {expiry_str}. Please contact your vendor for renewal.", info
        except ValueError:
            return False, "Invalid expiry date specified in license.", None

    return True, "License valid and active.", info

def save_license(token_str):
    """Saves the license key to license.dat."""
    token_str = token_str.strip()
    with open(LICENSE_FILE, "w", encoding="utf-8") as f:
        f.write(token_str)

def load_license():
    """Loads the license key from license.dat if present."""
    if os.path.exists(LICENSE_FILE):
        try:
            with open(LICENSE_FILE, "r", encoding="utf-8") as f:
                return f.read().strip()
        except Exception:
            return ""
    return ""

def is_software_activated():
    """Quick check if software has a valid, active license for this machine or cloud deployment."""
    # Web / Cloud bypass mode (for Render, Cloud deployment, or WEB_MODE=1)
    if os.environ.get('WEB_MODE', '').lower() in ('true', '1', 'yes') or os.environ.get('RENDER') or os.environ.get('DISABLE_LICENSE', '').lower() in ('true', '1'):
        return True, "Web Cloud Edition Active (Lifetime)", {
            "client_name": "Web Multi-User Cloud Edition",
            "machine_id": "CLOUD-WEB-SERVER",
            "expiry": "LIFETIME",
            "issued_at": "2026-01-01"
        }

    token = load_license()
    if not token:
        return False, "Software not activated. Please enter license key.", None
    return verify_license_token(token)

def get_license_details():
    """Returns license details dictionary or None."""
    if os.environ.get('WEB_MODE', '').lower() in ('true', '1', 'yes') or os.environ.get('RENDER') or os.environ.get('DISABLE_LICENSE', '').lower() in ('true', '1'):
        return {
            "is_valid": True,
            "client_name": "Web Multi-User Cloud Edition",
            "machine_id": "CLOUD-WEB-SERVER",
            "expiry": "LIFETIME",
            "issued_at": "2026-01-01",
            "status_text": "Active (Lifetime Web Edition)"
        }

    token = load_license()
    if not token:
        return None
    valid, msg, info = verify_license_token(token)
    if valid and info:
        return {
            "is_valid": True,
            "client_name": info.get("client_name", "Registered Client"),
            "machine_id": info.get("machine_id", get_machine_id()),
            "expiry": info.get("expiry", "LIFETIME"),
            "issued_at": info.get("issued_at", ""),
            "status_text": f"Active ({'Lifetime' if info.get('expiry') == 'LIFETIME' else 'Expires ' + str(info.get('expiry'))})"
        }
    elif info:
        return {
            "is_valid": False,
            "client_name": info.get("client_name", "Unlicensed"),
            "machine_id": info.get("machine_id", get_machine_id()),
            "expiry": info.get("expiry", "Expired"),
            "status_text": msg
        }
    return None
